using EngineLayer.DIA.FeatureAlign;
using NUnit.Framework;
using System.Linq;

namespace Test.DIATests.Manuscript
{
    /// <summary>
    /// Self-test for <see cref="FeatureQuantStats"/> - the C# port of the manuscript's numeric core
    /// (replicate-CV precision and yeast differential expression). Every expected value is the exact
    /// numpy/scipy result (generated by scratchpad/ref_values.py), so a pass proves the C# reproduces
    /// the Python computation, not merely that it is self-consistent. Runs in the normal suite; no data on disk.
    /// </summary>
    [TestFixture]
    public class FeatureQuantStatsTest
    {
        private const double Exact = 1e-12;   // pure arithmetic must match to machine precision
        private const double PTol = 1e-9;     // incomplete-beta p-values match scipy to ~1e-9

        // ------------------------------------------------------------ moments / CV

        [Test]
        public void SampleMoments_MatchNumpyDdof1()
        {
            var x = new[] { 2.0, 4.0, 6.0 };
            Assert.That(FeatureQuantStats.Mean(x), Is.EqualTo(4.0).Within(Exact));
            Assert.That(FeatureQuantStats.SampleVariance(x), Is.EqualTo(4.0).Within(Exact)); // ddof=1
            Assert.That(FeatureQuantStats.SampleStdDev(x), Is.EqualTo(2.0).Within(Exact));
        }

        [Test]
        public void CoefficientOfVariation_MatchesNumpy()
        {
            Assert.That(FeatureQuantStats.CoefficientOfVariation(new[] { 2.0, 4.0, 6.0 }), Is.EqualTo(0.5).Within(Exact));
            Assert.That(FeatureQuantStats.CoefficientOfVariation(new[] { 100.0, 110.0, 90.0 }), Is.EqualTo(0.1).Within(Exact));
            Assert.That(FeatureQuantStats.CoefficientOfVariation(new[] { 5.0, 5.0, 5.0 }), Is.EqualTo(0.0).Within(Exact));
        }

        [Test]
        public void SizeFactors_AreMeanOverValue()
        {
            var sf = FeatureQuantStats.SizeFactors(new[] { 2.0, 1.0, 1.0 });
            Assert.That(sf[0], Is.EqualTo(0.6666666666666666).Within(Exact));
            Assert.That(sf[1], Is.EqualTo(1.3333333333333333).Within(Exact));
            Assert.That(sf[2], Is.EqualTo(1.3333333333333333).Within(Exact));

            var sf2 = FeatureQuantStats.SizeFactors(new[] { 1.2, 0.8, 1.0 });
            Assert.That(sf2[0], Is.EqualTo(0.8333333333333334).Within(Exact));
            Assert.That(sf2[1], Is.EqualTo(1.25).Within(Exact));
            Assert.That(sf2[2], Is.EqualTo(1.0).Within(Exact));
        }

        [Test]
        public void ReplicateCv_AppliesSizeFactorsThenCv()
        {
            // vals [10,10,10], loading [2,1,1] -> sf [0.6667,1.333,1.333] -> CV = sqrt(0.12)
            var sf = FeatureQuantStats.SizeFactors(new[] { 2.0, 1.0, 1.0 });
            double cv = FeatureQuantStats.ReplicateCv(new[] { 10.0, 10.0, 10.0 }, sf);
            Assert.That(cv, Is.EqualTo(0.34641016151377546).Within(Exact));
        }

        [Test]
        public void SizeFactors_CancelInCv_WhenAllRunsScaledEqually()
        {
            // a global constant loading -> all size factors 1 -> CV unchanged (the reference cancels)
            var vals = new[] { 3.0, 7.0, 5.0 };
            double bare = FeatureQuantStats.CoefficientOfVariation(vals);
            var sf = FeatureQuantStats.SizeFactors(new[] { 9.0, 9.0, 9.0 });
            Assert.That(FeatureQuantStats.ReplicateCv(vals, sf), Is.EqualTo(bare).Within(Exact));
        }

        [Test]
        public void MedianAndPercentile_MatchNumpyLinear()
        {
            var x = new[] { 9.0, 11.0, 10.0, 12.0 };        // even n -> average of middles
            Assert.That(FeatureQuantStats.Median(x), Is.EqualTo(10.5).Within(Exact));
            // numpy 'linear' percentile
            Assert.That(FeatureQuantStats.Percentile(x, 25), Is.EqualTo(9.75).Within(Exact));
            Assert.That(FeatureQuantStats.Percentile(x, 75), Is.EqualTo(11.25).Within(Exact));
            Assert.That(FeatureQuantStats.InterquartileRange(x), Is.EqualTo(1.5).Within(Exact));
        }

        // -------------------------------------------------- median-ratio size factors

        [Test]
        public void MedianRatioSizeFactors_MatchS2Normalization()
        {
            double[][] m =
            {
                new[] { 10.0, 20.0, 40.0 },
                new[] { 12.0, 18.0, 44.0 },
                new[] {  9.0, 22.0, 39.0 },
                new[] { 11.0, 19.0, 42.0 },
            };
            var sf = FeatureQuantStats.MedianRatioSizeFactors(m);   // per-run medians [10.5,19.5,41.0]
            Assert.That(sf[0], Is.EqualTo(1.8571428571428572).Within(Exact));
            Assert.That(sf[1], Is.EqualTo(1.0).Within(Exact));
            Assert.That(sf[2], Is.EqualTo(0.47560975609756095).Within(Exact));
        }

        // ------------------------------------------------------- Welch t-test

        [Test]
        public void WelchTTest_MatchesScipyUnequalVar()
        {
            var a = new[] { 10.0, 12.0, 14.0 };
            var b = new[] { 20.0, 26.0, 23.0 };
            var (t, df, p) = FeatureQuantStats.WelchTTest(b, a);   // scipy ttest_ind(b, a, equal_var=False)
            Assert.That(t, Is.EqualTo(5.284229075567875).Within(Exact));
            Assert.That(df, Is.EqualTo(3.484536082474226).Within(Exact));
            Assert.That(p, Is.EqualTo(0.008962770427501474).Within(PTol));
        }

        [Test]
        public void StudentTwoSidedP_MatchesScipyAcrossRange()
        {
            // (t, df) -> expected two-sided p, from scipy 2*t.sf(|t|, df)
            (double t, double df, double p)[] cases =
            {
                (2.0,   4.0,   0.11611652351681556),
                (3.5,   3.1,   0.037491888933967356),
                (0.5,  10.0,   0.6278936057429729),
                (1.234, 5.678, 0.2658262334593384),
                (6.0,   2.0,   0.02667147321542477),
            };
            foreach (var c in cases)
                Assert.That(FeatureQuantStats.StudentTwoSidedP(c.t, c.df), Is.EqualTo(c.p).Within(PTol),
                    $"t={c.t}, df={c.df}");
        }

        [Test]
        public void WelchP_IsSignIndependent()
        {
            var a = new[] { 10.0, 12.0, 14.0 };
            var b = new[] { 20.0, 26.0, 23.0 };
            Assert.That(FeatureQuantStats.WelchTTest(a, b).p,
                Is.EqualTo(FeatureQuantStats.WelchTTest(b, a).p).Within(Exact));
        }

        // ------------------------------------------------------- Benjamini-Hochberg

        [Test]
        public void BenjaminiHochberg_MatchesScriptLoop()
        {
            var p = new[] { 0.001, 0.008, 0.039, 0.041, 0.9 };
            var q = FeatureQuantStats.BenjaminiHochberg(p);
            var expected = new[] { 0.005, 0.02, 0.051250000000000004, 0.051250000000000004, 0.9 };
            for (int i = 0; i < p.Length; i++)
                Assert.That(q[i], Is.EqualTo(expected[i]).Within(Exact), $"q[{i}]");
        }

        [Test]
        public void BenjaminiHochberg_IsMonotoneAndBounded()
        {
            var p = new[] { 0.2, 0.001, 0.5, 0.03, 0.9, 0.04 };
            var q = FeatureQuantStats.BenjaminiHochberg(p);
            Assert.That(q.All(v => v <= 1.0 + Exact), "q-values must be <= 1");
            // sorted by p, q must be non-decreasing
            var byP = Enumerable.Range(0, p.Length).OrderBy(i => p[i]).Select(i => q[i]).ToArray();
            for (int i = 1; i < byP.Length; i++)
                Assert.That(byP[i], Is.GreaterThanOrEqualTo(byP[i - 1] - Exact), $"monotone at {i}");
        }

        // -------------------------------------------------- DE per-feature pipeline

        [Test]
        public void LogFcWelch_MatchesScipyEndToEnd()
        {
            var g1 = new[] { 100.0, 120.0, 110.0 };   // condition 1-1
            var g2 = new[] { 210.0, 190.0, 205.0 };   // condition 1-2
            var (fc, p) = FeatureQuantStats.LogFcWelch(g1, g2);
            Assert.That(fc, Is.EqualTo(0.8771582421982034).Within(Exact));
            Assert.That(p, Is.EqualTo(0.001632314081468705).Within(PTol));
        }
    }
}
